        add     x0,a
        move    #>$0008a0,n1
        move    a,x:(r1+n1)
        move    b,x1
        move    x:(r7+$15),x0
        mpyr    x1,x0,a
        move    x:(r7+$0c),x0
        add     x0,a
        move    #>$001200,n1
        move    a,x:(r1+n1)
        move    y1,a
        add     y0,a                    ; h1
        move    y1,b
        sub     y0,b                    ; h3
        move    a,x1
        move    x:(r7+$14),x0
        mpyr    x1,x0,a
        move    x:(r7+$0c),x0
        sub     x0,a
        move    #>$000caf,n1
        move    a,x:(r1+n1)
        move    b,x1
        move    x:(r7+$16),x0
        mpyr    x1,x0,a
        move    x:(r7+$0c),x0
        sub     x0,a
        move    #>$001873,n1
        move    a,x:(r1+n1)
; out = dry + curtains
        move    x:(r7+$0d),a
        asl     #$2,a,a
        move    x:(r0),x0
        add     x0,a
        move    a,x:(r0)+
        move    x:(r7+$0e),b
        asl     #$2,b,b
        move    x:(r0),x0
        add     x0,b
        move    b,x:(r0)+
        move    (r1)-
auframes:
        nop
        move    r1,x:(r7+$02)
        move    #>$ffffff,m1
; the rider: the largest of the four lines' damped reads (the last frame) over 0.4 of the line scale rides the
; injection down 1/4 a call; under it the rider comes back 2^-10 a call. A long TIME on loud sound
; can no longer stack the lines into their limit (the plugin's float lines would only grow)
        move    x:(r7+$0f),a
        abs     a
        move    x:(r7+$10),b
        abs     b
        move    b,x0
        cmp     x0,a
        tlt     x0,a
        move    x:(r7+$11),b
        abs     b
        move    b,x0
        cmp     x0,a
        tlt     x0,a
        move    x:(r7+$12),b
        abs     b
        move    b,x0
        cmp     x0,a
        tlt     x0,a
        cmp     #>$333333,a
        move    x:(r7+$35),b
        ble     aurok
        move    b,x0
        move    #>$200000,y0
        mpy     y0,x0,a
        sub     a,b
        bra     aurset
aurok:
        move    #>$7fffff,a
        sub     b,a
        asr     #$a,a,a
        add     a,b
aurset:
        move    b,x:(r7+$35)
; quiet? (the last frame's curtains, both sides, against 512 LSB)
        move    x:(r7+$0d),a
        abs     a
        move    x:(r7+$0e),b
        abs     b
        add     b,a
        asl     #$2,a,a
        cmp     #>$000200,a
        ble     auquiet
        clr     a
        move    a,x:(r7+$2f)
        rts
auquiet:
        move    x:(r7+$2f),a
        cmp     #>$000562,a
        bge     auqx
        add     #>$1,a
        move    a,x:(r7+$2f)
auqx:
        rts
; ---- subroutines (after their callers) ----
; the anti-alias low-pass coefficients for this SHFT: B A1H A2 CH P K (see gen.py aa_coefs)
auzaa:
        move    x:(r7+$07),a
        cmp     #>$000000,a
        bne     auzb12
        move    #>$200000,x0
        move    x0,x:(r7+$37)
        move    #>$000000,x0
        move    x0,x:(r7+$38)
        move    #>$000000,x0
        move    x0,x:(r7+$39)
        move    #>$000000,x0
        move    x0,x:(r7+$3a)
        move    #>$000000,x0
        move    x0,x:(r7+$3b)
        move    #>$000000,x0
        move    x0,x:(r7+$3c)
        rts
auzb12:
        cmp     #>$000001,a
        bne     auzb19
        move    #>$02714c,x0
        move    x0,x:(r7+$37)
        move    #>$2e6b8f,x0
        move    x0,x:(r7+$38)
        move    #>$a9ab95,x0
        move    x0,x:(r7+$39)
        move    #>$42da7a,x0
        move    x0,x:(r7+$3a)
        move    #>$4151ac,x0
        move    x0,x:(r7+$3b)
        move    #>$7fffff,x0
        move    x0,x:(r7+$3c)
        rts
auzb19:
        cmp     #>$000002,a
        bne     auzb24
        move    #>$013451,x0
        move    x0,x:(r7+$37)
        move    #>$5624ba,x0
        move    x0,x:(r7+$38)
        move    #>$9e6df3,x0
        move    x0,x:(r7+$39)
        move    #>$f21bae,x0
        move    x0,x:(r7+$3a)
        move    #>$56bbb3,x0
        move    x0,x:(r7+$3b)
        move    #>$7fffff,x0
        move    x0,x:(r7+$3c)
        rts
auzb24:
        move    #>$00b668,x0
        move    x0,x:(r7+$37)
        move    #>$66bd9b,x0
        move    x0,x:(r7+$38)
        move    #>$9707c2,x0
        move    x0,x:(r7+$39)
        move    #>$c7958f,x0
        move    x0,x:(r7+$3a)
        move    #>$624fb9,x0
        move    x0,x:(r7+$3b)
        move    #>$7fffff,x0
        move    x0,x:(r7+$3c)
        rts
aurand:
        move    x:(r7+$05),x0
        move    #>$0343fd,y0
        mpy     y0,x0,a
        asr     a                       ; a1:a0 = the whole product, a0 its low 24 bits
        move    a0,x0
        move    x0,a
        add     #>$269ec3,a
        move    a1,x:(r7+$05)
        move    a1,b
        lsr     b
        move    b1,x0
        move    x0,a
        rts
auexp:
        move    a1,b
        asr     #$12,a,a  ; a1 = n = floor(y)
        add     #>$1,a
        move    a1,x1  ; n + 1 (never 0: a do count of 0 is not a skip)
        and     #>$03ffff,b
        asl     #$5,b,b  ; f in Q23, b2 stays 0
        move    b1,x0
        move    #>$2c5c86,y0
        mpy     y0,x0,b
        move    b,y0  ; g = f ln2 / 2
        move    #>$02aaab,x0
        mpy     y0,x0,b
        sub     #>$0aaaab,b
        move    b,x0
        mpy     y0,x0,b
        add     #>$200000,b
        move    b,x0
        mpy     y0,x0,b
        sub     #>$400000,b
        move    b,x0
        mpy     y0,x0,b
        add     #>$400000,b  ; e^-g / 2
        move    b,x0
        mpy     x0,x0,b
        asl     #$2,b,b  ; 2^-f in (0.5, 1]
        do      x1,>aupow
        asr     b
aupow:
        asl     b
        rts
ausin:
        mpy     x0,x0,a
        move    a,x1                    ; u^2
        move    #>$04a277,y0
        mpy     x1,y0,a
        add     #>$d6de19,a
        move    a,y0
        mpy     x1,y0,a
        add     #>$648200,a
        move    a,y0
        mpy     y0,x0,a                 ; 0.5 sin(pi u / 2)
        rts
